record.field:
BASE_URL = 'https://thirdparty.playtomic.io'
TIMEOUT = 30


def get_token():
    return env.company.x_playtomic_token or ''


def regenerate_token():
    env.ref('sports_club_playtomic.action_playtomic_generate_token').run()
    return get_token()


def get_header(token=None):
    headers = {'Content-Type': 'application/json'}
    if token:
        headers['Authorization'] = 'Bearer %s' % token
    return headers


def send(method, url, token):
    if method == 'POST':
        return requests.post(url, json=req.get('payload') or {}, headers=get_header(token), timeout=TIMEOUT)
    # GET: query parameters only, never a JSON body
    return requests.get(url, params=req.get('params') or {}, headers=get_header(token), timeout=TIMEOUT)


req = env.context.get('playtomic_request')
if not isinstance(req, dict):
    _logger.error("Playtomic: API Request called without a 'playtomic_request' dict in context.")
    log("Playtomic: API Request called without a 'playtomic_request' dict in context.", level='error')
else:
    req.update({'ok': False, 'status_code': None, 'data': None, 'error': None})
    method = (req.get('method') or 'GET').upper()
    endpoint = req.get('endpoint') or ''
    url = BASE_URL + endpoint
    use_token = bool(req.get('use_token'))

    _logger.info('Playtomic: %s %s (use_token=%s, params=%s)', method, endpoint, use_token,
                 req.get('params') if method == 'GET' else None)
    try:
        token = ''
        if use_token:
            # Token empty check (token generation uses use_token=False -> no recursion)
            token = get_token()
            if not token:
                _logger.info('Playtomic: no stored token, generating a new one.')
                token = regenerate_token()
            if not token:
                req['error'] = ("No Playtomic token available. Check the playtomic.client_id and "
                                "playtomic.secret system parameters and the 'Playtomic: Generate Token' logs.")

        if not req['error']:
            res = send(method, url, token)
            _logger.info('Playtomic: %s %s -> HTTP %s', method, endpoint, res.status_code)

            # 401 / 403: regenerate the token and retry ONCE
            if use_token and res.status_code in (401, 403) and not req.get('retried'):
                req['retried'] = True
                _logger.warning('Playtomic: %s %s returned HTTP %s, regenerating the token and retrying once.',
                                method, endpoint, res.status_code)
                log('Playtomic: %s %s returned HTTP %s, regenerating the token and retrying once.'
                    % (method, endpoint, res.status_code), level='warning')
                token = regenerate_token()
                if token:
                    res = send(method, url, token)
                    _logger.info('Playtomic: retry %s %s -> HTTP %s', method, endpoint, res.status_code)

            req['status_code'] = res.status_code
            if use_token and res.status_code in (401, 403):
                req['error'] = ('Playtomic refused the token (HTTP %s) even after regenerating it once: %s'
                                % (res.status_code, (res.text or '')[:500]))
            elif 200 <= res.status_code < 300:
                if res.content:
                    try:
                        req['data'] = res.json()
                    except Exception as e:
                        req['error'] = 'Invalid JSON in the Playtomic response: %s' % repr(e)
                req['ok'] = not req['error']
            else:
                req['error'] = 'HTTP %s: %s' % (res.status_code, (res.text or '')[:500])
    except Exception as e:
        req['ok'] = False
        req['error'] = 'Request error: %s' % repr(e)

    if req['error']:
        # Never log the payload: it contains the secret
        _logger.error('Playtomic: %s %s failed: %s', method, endpoint, req['error'])
        log('Playtomic: %s %s failed: %s' % (method, endpoint, req['error']), level='error')
    else:
        _logger.info('Playtomic: %s %s succeeded.', method, endpoint)
